/** Machines this species can learn, as MachineDefs, in catalog order. */
export function machinesForSpecies(speciesKey: string): MachineDef[] {
  return (machineLearnsets[speciesKey] ?? []).map((id) => machines[id]).filter(Boolean);
}

/** Can this species learn this machine? */
export function canLearnMachine(speciesKey: string, machineId: string): boolean {
  return (machineLearnsets[speciesKey] ?? []).includes(machineId);
}
